import * as T from './vendor/three.module.min.js';
import {initializeTikiTextures,tikiMaterials} from './tiki-materials-v76.js';
const textures=new Map();let pending;
const surfaces={moai:'idols/moai-stone',masonry:'idols/pond-masonry',bronze:'idols/lantern-brass',blackMetal:'idols/cone-lamp-steel',canoe:'buffet/canoe',rug:'buffet/rug',pineapple:'fruit/pineapple',melon:'fruit/cantaloupe'};
const graphics={porcelain:'buffet/ceramic-crazing',idolFace:'idols/tiki-front-basecolor',idolWood:'idols/tiki-wood-basecolor',blueMug:'cocktails/blue-tiki-wrap',brownMug:'cocktails/brown-tiki-wrap',wahine:'cocktails/tan-wahine-wrap',greenCeramic:'cocktails/green-mug-ashtray-atlas',glazes:'cocktails/ceramic-coaster-atlas',garnish:'cocktails/garnish-sheet',fern:'botanical/boston-fern',palm:'botanical/areca-palm',strelitzia:'botanical/bird-of-paradise',vine:'botanical/hanging-fern-vine',lei:'botanical/hawaiian-lei',lily:'botanical/lily-orchid-atlas',labels1:'bottles/labels-atlas-01',labels2:'bottles/labels-atlas-02',labels3:'bottles/labels-atlas-03',beerSign:'bottles/cold-beer-sign',toy:'bottles/vw-t1-atlas',decor:'bottles/detail-atlas',coconut:'buffet/coconut-ladle-ceramic-atlas',dollWhite:'buffet/menehune-white-atlas',dollPink:'buffet/menehune-pink-atlas',iceOrchids:'buffet/ice-orchids-atlas',papayaGreen:'fruit/papaya-green-basecolor',papayaYellow:'fruit/papaya-yellow-basecolor',crown:'fruit/pineapple-crown',surfboard:'fruit/surfboard-front',umbrella:'fruit/cocktail-umbrella-canopy'};
async function texture(key,path,color=true,repeat=false){if(textures.has(key))return textures.get(key);const t=await new T.TextureLoader().loadAsync(new URL('./textures/tiki-v77/'+path+'.webp',import.meta.url).href).catch(()=>{throw new Error('Tiki texture did not decode: '+path);});t.name='V77 generated / '+path;t.colorSpace=color?T.SRGBColorSpace:T.NoColorSpace;t.wrapS=t.wrapT=repeat?T.RepeatWrapping:T.ClampToEdgeWrapping;t.anisotropy=4;t.minFilter=T.LinearMipmapLinearFilter;t.magFilter=T.LinearFilter;textures.set(key,t);return t;}
export function initializeTiki77(report=()=>{}){if(pending)return pending;pending=(async()=>{await Promise.all([initializeTikiTextures(false),initializeTikiTextures(true)]);let done=0;const jobs=[];for(const [k,p]of Object.entries(surfaces))for(const channel of['basecolor','normal','roughness','ao','height','metalness']){const c=channel==='metalness'&&!p.startsWith('idols')?'metallic':channel;jobs.push([k+'/'+channel,p+'-'+c,channel==='basecolor',true]);}for(const [k,p]of Object.entries(graphics))jobs.push([k,p,true,false]);jobs.push(['papayaGreenNormal','fruit/papaya-green-normal',false,true],['papayaYellowNormal','fruit/papaya-yellow-normal',false,true]);
 // Bounded decode concurrency prevents 80 decoded bitmaps landing in one frame.
 let cursor=0;await Promise.all(Array.from({length:5},async()=>{while(cursor<jobs.length){const job=jobs[cursor++];await texture(...job);report(++done/jobs.length);}}));})();return pending.catch(e=>{pending=null;throw e;});}
export function tiki77Materials(){const m=tikiMaterials(true),tex=k=>textures.get(k);
 const surface=(key,roughness=.7,normal=.7,physical=false)=>{const o={name:'V77 '+key,map:tex(key+'/basecolor'),normalMap:tex(key+'/normal'),normalScale:new T.Vector2(normal,normal),roughnessMap:tex(key+'/roughness'),roughness,aoMap:tex(key+'/ao'),aoMapIntensity:.85,metalnessMap:tex(key+'/metalness'),metalness:0};return physical?new T.MeshPhysicalMaterial({...o,clearcoat:.85,clearcoatRoughness:.12}):new T.MeshStandardMaterial(o);};
 for(const key of Object.keys(surfaces))m[key]=surface(key,key==='moai'?.34:key==='bronze'?.48:.83,key==='moai'?1.15:.75,['moai','masonry','pineapple','melon'].includes(key));m.moai.normalScale.set(.48,.48);m.moai.roughness=.28;m.filterGray=m.masonry.clone();m.filterGray.color.setHex(0x96a4a2);m.filterGray.roughness=.47;m.filterGray.clearcoat=.1;m.bronze.metalness=.85;m.blackMetal.metalness=.72;m.blackMetal.roughness=.65;m.canoe.side=T.DoubleSide;m.rug.roughness=1;m.rug.aoMapIntensity=.5;
 const coat=(key,rough=.28)=>new T.MeshPhysicalMaterial({name:'Generated glazed '+key,map:tex(key),roughness:rough,normalMap:m.counter.normalMap,normalScale:new T.Vector2(.055,.055),clearcoat:1,clearcoatRoughness:.11,side:T.DoubleSide});
 for(const key of['porcelain','blueMug','brownMug','wahine','greenCeramic','glazes','coconut','dollWhite','dollPink','toy'])m[key]=coat(key,key.startsWith('doll')?.38:.24);
 for(const key of['labels1','labels2','labels3','decor','beerSign'])m[key]=new T.MeshStandardMaterial({name:'Generated period '+key,map:tex(key),roughness:.60,metalness:key==='beerSign'?.3:0,side:T.DoubleSide});
 m.idolFace=coat('idolFace',.64);m.idolFace.normalScale.set(.22,.22);m.idolWood=new T.MeshStandardMaterial({name:'Carved idol rear',map:tex('idolWood'),normalMap:m.wood.normalMap,normalScale:new T.Vector2(.9,.9),roughness:.84});
 for(const key of['garnish','fern','palm','strelitzia','vine','lei','lily','iceOrchids','crown','surfboard','umbrella']){m[key]=new T.MeshStandardMaterial({name:'Generated alpha cutout / '+key,map:tex(key),alphaTest:.35,side:T.DoubleSide,roughness:key==='surfboard'?.33:.72,metalness:0});}
 for(const key of['papayaGreen','papayaYellow'])m[key]=new T.MeshPhysicalMaterial({name:key,map:tex(key),normalMap:tex(key+'Normal'),normalScale:new T.Vector2(.27,.27),roughness:.48,clearcoat:.55,clearcoatRoughness:.22});
 m.clay=new T.MeshStandardMaterial({name:'Unglazed terracotta backs',map:tex('canoe/basecolor'),color:0x613b28,normalMap:tex('canoe/normal'),normalScale:new T.Vector2(.10,.10),roughness:.65});
 m.steel=new T.MeshStandardMaterial({name:'Brushed pour spouts',map:tex('bronze/basecolor'),color:0xc7d5d5,normalMap:tex('blackMetal/normal'),normalScale:new T.Vector2(.14,.14),roughness:.28,metalness:.93});
 m.ivory=new T.MeshStandardMaterial({name:'Old ivory plastic',map:tex('porcelain'),color:0xf4e5ca,roughness:.42});m.toyBlue=m.ivory.clone();m.toyBlue.color.setHex(0x174578);m.toyBlue.roughness=.33;m.purple=m.ivory.clone();m.purple.color.setHex(0x942cbd);m.coffee=m.dark.clone();m.coffee.color.setHex(0x28130c);
 // The existing generated slate/wood/vinyl maps remain: only their wet finish
 // changes. No uniform lighting boost, no replacement of the original fabric.
 for(const key of['counter','vinyl']){const old=m[key],p=new T.MeshPhysicalMaterial();T.MeshStandardMaterial.prototype.copy.call(p,old);p.clearcoat=key==='counter'?.65:.24;p.clearcoatRoughness=.24;p.roughness=key==='counter'?.42:.56;m[key]=p;old.dispose();}
 m.umbrella.color.setHex(0xbfa8a0);m.mat.color.setHex(0x82725a);m.floor.roughness=.57;m.floor.normalScale.set(.9,.9);m.sign.emissiveIntensity=.65;
 m.lanternGlow=new T.MeshStandardMaterial({name:'Ruby lantern mantle',color:0xcc2711,emissive:0xff2609,emissiveIntensity:2.8,roughness:.2});
 m.pondGreen=new T.MeshStandardMaterial({name:'Submerged green lamp',color:0xaed152,emissive:0x86ff26,emissiveIntensity:1.5});m.pondGold=m.pondGreen.clone();m.pondGold.emissive.setHex(0xffba36);m.pondGold.color.setHex(0xf4bc63);
 return{m,textures,tex};}
